import {addReference} from './inventory-model.js?v=17';
import {contractTemplate,receiveTools} from './workbook-model.js?v=17';
import {total} from './data.js?v=17';

export function createIntake(a) {
  const {esc,money,fullDate,icon,btn,pill,link,empty}=a;
  const uid=p=>p+'-'+crypto.randomUUID();
  const steps=(labels,active)=>`<ol class="flow-steps">${labels.map((label,i)=>`<li class="${i===active?'active':i<active?'complete':''}"><span>${i<active?'✓':i+1}</span>${label}</li>`).join('')}</ol>`;
  const sendSteps=i=>steps(['Enviar','Tratar','Vincular'],i);
  const options=(type,selected='',blank='Sem vínculo por enquanto')=>`<option value="">${blank}</option>${a.scope(type).map(x=>`<option value="${x.id}" ${selected===x.id?'selected':''}>${esc(x.name||x.title)}${x.competence?' · '+x.competence:''}</option>`).join('')}`;
  function plan(d){a.state.intake??={};return a.state.intake[d.id]??={method:/\.(jpg|jpeg|png|webp)$/i.test(d.name)?'ocr':'direct',text:'',note:'',stage:'received'};}
  const cards=items=>`<div class="choice-grid">${items.map(([kind,id,title,description,ico])=>`<button class="choice-card" data-open="${kind}" data-id="${id||''}"><span class="choice-icon">${icon(ico)}</span><h3>${title}</h3><p>${description}</p><span class="choice-next">Continuar ${icon('chevron')}</span></button>`).join('')}</div>`;
  function add(){return {heading:'Adicionar',body:`<span class="eyebrow">${esc(a.get('companies',a.company).name)}</span><h2>Como você quer começar?</h2><p class="description">Traga algo que já existe ou crie a partir do seu contexto.</p>${cards([['send','','Enviar','Arquivo, foto, cobrança ou comprovante. Receba, trate e conecte ao seu contexto.','in'],['create','','Criar','Use modelos e informações de contratos, bens e obrigações já cadastrados.','plus']])}<div class="flow-footnote">Os dois caminhos chegam ao mesmo acervo da empresa, preservando origem e relacionamentos.</div>`}}
  function send(id){const demos=a.scope('documents').filter(d=>!d.local&&!d.originalUrl).slice(0,8);return {heading:'Enviar · ponto de entrada',body:sendSteps(0)+`<h2>O que você recebeu?</h2><p class="description">O arquivo pode chegar primeiro. A organização e os vínculos são construídos em seguida.</p><button class="upload-zone" data-open="newdoc" data-id="${esc(id||'')}">${icon('in')}<strong>Escolher arquivo do dispositivo</strong><span>PDF, JPG, PNG ou WebP · até 15 MB</span><small>Na prévia, o arquivo fica somente neste navegador.</small></button><div class="drawer-section"><h3>Experimente com os documentos de exemplo</h3><div class="sample-grid">${demos.map(d=>`<button class="sample-file" data-open="process" data-id="${d.id}">${icon(d.locked?'lock':d.name.endsWith('.jpg')?'eye':'file')}<span><b>${esc(d.name)}</b><small>${d.locked?'Protegido por senha':d.name.endsWith('.jpg')?'Imagem · caminho de OCR':`${d.pages.length} página(s) · caminho de leitura direta`}</small></span>${icon('chevron')}</button>`).join('')||'<p class="annotation">Envie um arquivo de teste para começar.</p>'}</div></div><div class="flow-footnote">Arquivos recebidos por e-mail, WhatsApp ou portal podem ser adicionados manualmente. Não há importação automática dessas fontes nesta prévia.</div>`}}
  function upload(id){return {heading:'Enviar · arquivo',body:sendSteps(0)+a.formShell('Receber um documento','Primeiro preserve a origem. Depois escolha as ferramentas e o contexto.',`${id?.startsWith('asset:')?`<div class="callout">${icon('asset')}<span>Documentação do ativo: <strong>${esc(a.get('assets',id.slice(6))?.name||'Ativo')}</strong><br>Você poderá ajustar as referências após o envio.</span></div>`:''}<label>Arquivo<input name="file" type="file" accept="application/pdf,image/png,image/jpeg,image/webp" required></label><div class="formrow"><label>De onde veio?<select name="source"><option>Dispositivo</option><option>E-mail</option><option>WhatsApp</option><option>Portal do fornecedor</option><option>Foto / digitalização</option></select></label><label>Como é o conteúdo?<select name="format"><option value="unknown">Ainda não sei</option><option value="text">PDF com texto selecionável</option><option value="scan">Imagem ou PDF digitalizado</option><option value="protected">Documento com senha</option></select></label></div><label>Observação inicial<textarea name="note" maxlength="400" placeholder="Ex.: comprovante da manutenção da Sala 105."></textarea></label><p class="annotation">Até 15 MB. O original é mantido e o mesmo arquivo não será adicionado duas vezes nesta empresa.</p>`,'receive-file',id||'','Receber e escolher tratamento')}}
  function process(id){const d=a.get('documents',id);if(!d||d.company!==a.company)return {heading:'Documento',body:empty('Documento indisponível')};const p=plan(d),locked=Boolean(d.locked);return {heading:'Enviar · mesa de tratamento',wide:true,body:sendSteps(1)+`<h2>${esc(d.name)}</h2><p class="description">${esc(d.source)} · ${fullDate(d.date)} · ${d.local?'Arquivo local preservado':'Documento fictício de demonstração'}</p><div class="processing-layout"><div><div class="source-card"><span class="choice-icon">${icon(locked?'lock':'file')}</span><div><h3>Original preservado</h3><p>${d.local?(p.format==='protected'?'Você indicou proteção por senha; o acesso ainda precisa ser tratado no processador PDF.':'Formato e conteúdo ainda precisam de conferência.'):`${d.pages?.length||1} página(s) de exemplo disponíveis.`}</p>${btn(locked?'Informar senha do exemplo':'Abrir documento',`data-open="document" data-id="${id}"`,'','eye')}</div></div><div class="drawer-section"><h3>Escolha a técnica de leitura</h3><div class="method-options">${receiveTools.slice(0,2).map(t=>`<button class="method-option ${p.method===t.id?'selected':''}" data-receive-method="${t.id}" data-id="${id}" aria-pressed="${p.method===t.id}">${icon(t.icon)}<span><b>${t.label}</b><small>${t.description}</small></span>${p.method===t.id?icon('check'):''}</button>`).join('')}</div><p class="annotation">A indicação é uma escolha de tratamento; confira se o arquivo permite leitura direta antes de usar OCR.</p></div>${locked?`<div class="callout">${icon('lock')}<span>Este exemplo precisa de senha antes da leitura. Abra o documento e use a senha de demonstração 1234.</span></div>`:d.local?`<div class="callout">${icon('info')}<span>Para arquivos enviados, esta prévia registra o plano e a tarefa de processamento. A extração real e o OCR ainda não estão conectados.</span></div>${btn('Registrar tarefa de processamento',`data-processing-task="${id}"`,'primary','task')}`:btn(p.text?'Refazer demonstração de leitura':'Experimentar leitura do exemplo',`data-extract-demo="${id}"`,'primary','eye')}<div class="drawer-section"><h3>${d.local?'Anotações para revisão':'Texto para revisão'}</h3>${p.text?`<span class="source-label">RESULTADO SIMULADO · ${p.method==='ocr'?'OCR':'LEITURA DIRETA'}</span>`:''}<textarea class="extracted-text" aria-label="Texto para revisão" data-process-text="${id}" placeholder="${d.local?'Registre manualmente o que conseguiu identificar.':'Execute a leitura do exemplo para visualizar o texto.'}">${esc(p.text||'')}</textarea><small class="annotation">Revise o conteúdo. Nenhum valor vira lançamento automaticamente.</small></div></div><aside class="tool-shelf"><h3>Ferramentas do documento</h3>${receiveTools.slice(2).map(t=>`<button class="tool-card" data-open="${t.id==='bundle'?'associate':'document'}" data-id="${id}">${icon(t.icon)}<span><b>${t.label}</b><small>${t.description}</small></span>${icon('chevron')}</button>`).join('')}<div class="selection-summary"><h4>Seleção atual</h4><p>${d.local?'O original completo será mantido. Seleção de páginas de arquivos locais requer o processador PDF.':`Páginas ${(a.state.selections[id]||d.pages.map((_,i)=>i)).map(n=>n+1).join(', ')} · sem alterar o original.`}</p></div><p class="annotation">“Organizar conjunto” relaciona os documentos no índice. Não mescla arquivos PDF nesta prévia.</p></aside></div><div class="drawer-actions">${btn('Continuar para vínculos',`data-open="associate" data-id="${id}"`,'primary','chevron')}${btn('Salvar tratamento para depois',`data-save-process="${id}"`,'','check')}</div>`}}
  function associate(id){const d=a.get('documents',id),p=plan(d);return {heading:'Enviar · classificação e vínculos',body:sendSteps(2)+a.formShell('Onde este documento se encaixa?','Revise o contexto e acrescente vínculos. O documento não efetiva pagamentos.',`<div class="source-pill">${icon('file')}<span>${esc(d.name)}</span>${pill(d.local?'Local':'Exemplo')}</div><label>Tipo do documento<select name="type">${['Comprovante','Fatura','Contrato','Nota fiscal','Recibo','Cobrança','Demonstrativo','Outro'].map(t=>`<option ${t===d.type?'selected':''}>${t}</option>`).join('')}</select></label><label>Obrigação relacionada<select name="obligation">${options('obligations',d.obligation)}</select></label><label>Contrato<select name="contract">${options('contracts',d.contract)}</select></label><label>Bem / ativo<select name="asset">${options('assets',d.asset)}</select></label><label>Contexto para a próxima pessoa<textarea name="note" maxlength="800" placeholder="A que este arquivo se refere e o que falta conferir?">${esc(p.note||d.note||'')}</textarea></label><label class="form-check"><input type="checkbox" name="reviewed" ${d.status==='Revisado'?'checked':''}>Conferi o documento e as informações acima</label><p class="annotation">Deixe a conferência desmarcada se ainda houver dúvida. Vínculos anteriores são preservados.</p>`,'associate-file',id,'Salvar organização')}}
  function create(){return {heading:'Criar · modelos e contexto',body:steps(['Escolher modelo','Preencher e revisar','Criar'],0)+`<h2>Comece com o que você já sabe.</h2><p class="description">Escolha um modelo e aproveite as informações da empresa.</p>${cards([['charge-template','','Cobrança de contrato','Reutilize partes, bem, vencimento e valor base. Revise aluguel, rateio e encargos.','contract'],['obligation-template','','Obrigação','Parta de manutenção, tributo ou despesa recorrente e indique o bem relacionado.','wallet'],['task-template','','Tarefa com contexto','Use uma rotina de conferência, solicitação ou revisão com prazo e vínculo.','task']])}<div class="drawer-section"><h3>Ampliar o inventário</h3><div class="drawer-actions">${btn('Cadastrar empresa','data-open="newcompany"','','company')}${btn('Cadastrar bem','data-open="newasset"','','asset')}</div></div>`}}
  function nextMonth(contract){let month=a.month;for(let i=0;i<24;i++){if(!a.state.obligations.some(o=>o.company===a.company&&o.contract===contract&&o.competence===month))return month;const dt=new Date(month+'-01T12:00:00Z');dt.setUTCMonth(dt.getUTCMonth()+1);month=dt.toISOString().slice(0,7)}return a.month}
  function chargeForm(id){const contracts=a.scope('contracts');if(!contracts.length)return {heading:'Criar cobrança',body:empty('Nenhum contrato disponível','Selecione uma empresa com contrato para experimentar este modelo.')};const current=a.current;current.templateContract??=contracts.some(c=>c.id===id)?id:contracts[0].id;current.templateMonth??=nextMonth(current.templateContract);const c=a.get('contracts',current.templateContract),draft=contractTemplate(a.state,c.id,current.templateMonth);const fields=current.fields||{},suggestedPercent=Number((c.rule.match(/(\d+(?:[.,]\d+)?)%/)||[])[1]?.replace(',','.')||0);const previous=a.state.obligations.find(o=>o.contract===c.id),fixed=previous?.items.filter(i=>i.nature.startsWith('Encargo')).reduce((n,i)=>n+i.amount,0)||0;return {heading:'Criar · cobrança de contrato',body:steps(['Escolher modelo','Preencher e revisar','Criar'],1)+a.formShell('Cobrança a partir do contrato','O modelo recupera os dados cadastrados. Confira a regra e os valores desta competência.',`<label>Contrato de origem<select name="contract" data-template-contract>${contracts.map(c=>`<option value="${c.id}" ${current.templateContract===c.id?'selected':''}>${esc(c.number+' · '+c.party+' · '+c.title)}</option>`).join('')}</select></label><div class="formrow"><label>Competência<input name="competence" type="month" value="${current.templateMonth}" data-template-month required></label><label>Vencimento<input name="due" type="date" value="${esc(fields.due||draft.due)}" required></label></div><div class="inherited-info"><span>${icon('link')} Informações aproveitadas</span><dl><div><dt>Empresa</dt><dd>${esc(a.get('companies',c.company).name)}</dd></div><div><dt>Contraparte</dt><dd>${esc(c.party)}</dd></div><div><dt>Bem</dt><dd>${esc(a.get('assets',c.asset)?.name||'Sem vínculo')}</dd></div><div><dt>Base contratual</dt><dd>${money(c.base)}</dd></div></dl><p>${esc(c.rule)}</p><small>${esc(c.revision)}</small></div><label>Conta financeira<select name="account">${a.scope('accounts').map(x=>`<option value="${x.id}" ${(fields.account||draft.account)===x.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select></label><div class="model-section"><h3>Composição desta competência</h3><div class="formrow"><label>Valor base (R$)<input name="base" inputmode="decimal" value="${esc(fields.base??(c.base/100).toFixed(2).replace('.',','))}" required></label><label>Encargos (R$)<input name="fixed" inputmode="decimal" value="${esc(fields.fixed??(fixed/100).toFixed(2).replace('.',','))}" required></label></div><small>Encargos são sugeridos a partir do lançamento anterior; confirme a regra vigente.</small><div class="formrow"><label>Valor da despesa para rateio (R$)<input name="sharedBase" inputmode="decimal" value="${esc(fields.sharedBase??'0,00')}" required></label><label>Participação (%)<input name="percent" type="number" min="0" max="100" step="0.01" value="${esc(fields.percent??suggestedPercent)}" required></label></div><label>Documento de origem do rateio<select name="sourceDoc">${options('documents',fields.sourceDoc||'','Escolha a origem se houver rateio')}</select></label><small>O rateio será calculado como despesa × participação. Confira a competência do documento escolhido.</small></div><label>Observação da composição<textarea name="note" maxlength="500" placeholder="Registre ajustes e a regra aplicada neste período.">${esc(fields.note||'')}</textarea></label><div class="form-error" role="alert"></div>`,'charge-template',c.id,'Revisar cobrança')}}
  function chargeReview(){const d=a.current.draft;if(!d)return {heading:'Revisar',body:empty('Preenchimento não encontrado')};return {heading:'Criar · revisão final',body:steps(['Escolher modelo','Preencher e revisar','Criar'],2)+`<h2>Confira antes de criar.</h2><p class="description">${esc(d.party)} · competência ${esc(d.competence)} · vencimento ${fullDate(d.due)}</p><div class="bigamount">${money(total(d))}</div>${d.items.map(i=>`<div class="component"><div class="row"><strong>${esc(i.name)}</strong><strong>${money(i.amount)}</strong></div><p>${esc(i.rule)}</p>${pill(i.nature)}</div>`).join('')}<div class="callout" style="margin-top:22px">${icon('info')}<span>Serão criados uma obrigação a receber e um demonstrativo de exemplo, vinculados ao contrato e ao bem. Nenhum recebimento será lançado ou cobrança enviada.</span></div><div class="drawer-actions">${btn('Criar obrigação e demonstrativo','data-confirm-charge="1"','primary','check')}${btn('Voltar e ajustar','data-action="back"')}</div>`}}
  function obligationModel(){return {heading:'Criar · modelo de obrigação',body:steps(['Escolher modelo','Preencher e revisar','Criar'],1)+a.formShell('Uma obrigação com origem','Use o modelo como ponto de partida; acrescente as informações do compromisso.',`<label>Modelo<select name="model"><option>Manutenção de um bem</option><option>Tributo ou taxa</option><option>Despesa recorrente</option></select></label><label>Descrição<input name="title" required maxlength="120" placeholder="Ex.: revisão elétrica da Sala 204"></label><label>Fornecedor / contraparte<input name="party" required maxlength="100"></label><div class="formrow"><label>Valor (R$)<input name="amount" inputmode="decimal" required placeholder="0,00"></label><label>Vencimento<input name="due" type="date" value="${a.dateContext}" required></label></div><label>Bem / ativo<select name="asset">${options('assets')}</select></label><label>Documento de origem<select name="doc">${options('documents')}</select></label><label>Conta<select name="account">${a.scope('accounts').map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join('')}</select></label><div class="form-error" role="alert"></div>`,'obligation-template','','Criar obrigação prevista')}}
  function taskModel(){return {heading:'Criar · modelo de tarefa',body:steps(['Escolher modelo','Preencher e revisar','Criar'],1)+a.formShell('Uma próxima ação, bem situada','A rotina e os vínculos ajudam a pessoa responsável a entender o que fazer.',`<label>Modelo<select name="model"><option>Conferir documento</option><option>Solicitar comprovante</option><option>Revisar composição da obrigação</option></select></label><label>Detalhe da ação<input name="detail" maxlength="120" placeholder="Ex.: confirmar os itens de água e condomínio"></label><label>Documento<select name="doc">${options('documents')}</select></label><label>Obrigação<select name="obligation">${options('obligations')}</select></label><div class="formrow"><label>Prazo<input name="due" type="date" value="${a.dateContext}" required></label><label>Responsável<select name="owner"><option>Você</option><option>Contabilidade</option></select></label></div>`,'task-template','','Criar tarefa vinculada')}}
  function dialog(kind,id){return ({add,send,create,newdoc:upload,process,associate,'charge-template':chargeForm,'charge-review':chargeReview,'obligation-template':obligationModel,'task-template':taskModel}[kind])?.(id)||null}
  function legacyDocumentExtras(d){return `<div class="drawer-section"><h3>Tratamento e contexto</h3>${d.profileCompany?btn('Abrir perfil da empresa','data-go="companies"','','company'):''}${btn('Abrir mesa de tratamento',`data-open="process" data-id="${d.id}"`,'','file')}${d.contract?link(a.get('contracts',d.contract)?.title,'contract',d.contract,'Contrato relacionado','contract'):''}${d.asset?link(a.get('assets',d.asset)?.name,'asset',d.asset,'Bem relacionado','asset'):''}${a.state.intake?.[d.id]?.note?`<p class="annotation">${esc(a.state.intake[d.id].note)}</p>`:''}</div>`}
  function documentExtras(d){return `<div class="drawer-section"><h3>Tratamento do documento</h3>${btn('Abrir mesa de tratamento',`data-open="process" data-id="${d.id}"`,'','file')}${a.state.intake?.[d.id]?.note?`<p class="annotation">${esc(a.state.intake[d.id].note)}</p>`:''}</div>`}
  function click(ds){
    if(ds.receiveMethod){plan(a.get('documents',ds.id)).method=ds.receiveMethod;a.save();a.draw();return true}
    if(ds.extractDemo){const d=a.get('documents',ds.extractDemo);if(d.local||d.locked){a.toast('Abra o documento e resolva o acesso antes da leitura.');return true}const p=plan(d);p.text=d.pages.map((page,i)=>`PÁGINA ${i+1} · ${page.title}\n${page.subtitle}\n${page.lines.join('\n')}`).join('\n\n');p.stage='read';a.save();a.draw();a.toast('Leitura de demonstração preparada para revisão.');return true}
    if(ds.processingTask){const d=a.get('documents',ds.processingTask),p=plan(d);const key='process:'+d.id+':'+p.method;if(!a.state.tasks.some(t=>t.processKey===key&&!t.done))a.state.tasks.push({id:uid('t'),company:a.company,title:(p.method==='ocr'?'Executar OCR':'Extrair texto nativo')+' · '+d.name,due:a.NOW,owner:'Você',kind:'Documento',doc:d.id,processKey:key,done:false});p.stage='pending';a.save();a.render();a.toast('Tarefa de processamento registrada. Nenhuma extração foi executada.');return true}
    if(ds.saveProcess){a.save();a.toast('Plano de tratamento salvo neste navegador.');return true}
    if(ds.confirmCharge){const draft=a.current.draft;if(!draft)return true;if(a.state.obligations.some(o=>o.company===a.company&&o.contract===draft.contract&&o.competence===draft.competence)){a.toast('Esta competência já tem uma cobrança para o contrato.');return true}const id=uid('o'),docId=uid('doc');const obligation={...draft,id,docs:[docId]};a.state.obligations.push(obligation);a.state.documents.push({id:docId,company:a.company,name:`Demonstrativo · ${draft.party} · ${draft.competence}`,type:'Cobrança',source:'Criado com modelo de contrato',date:a.NOW,status:'A revisar',obligation:id,contract:draft.contract,asset:draft.asset,pages:[{title:'Demonstrativo da cobrança',subtitle:`${draft.party} · ${draft.competence}`,lines:[...draft.items.map(i=>`${i.name}: ${money(i.amount)}. ${i.rule}`),`Total: ${money(total(draft))}. Vencimento: ${fullDate(draft.due)}.`,draft.note||'Conferir composição antes da emissão.']}]});a.state.notes[id]=draft.note;a.save();a.setMonth(draft.competence);a.closeAll();a.navigate('obligations');a.open('obligation',id);a.toast('Obrigação e demonstrativo criados no exemplo, sem movimento bancário.');return true}
    return false;
  }
  function change(e){const ds=e.target.dataset;if(ds.processText){plan(a.get('documents',ds.processText)).text=e.target.value;a.save();return true}if(e.target.hasAttribute('data-template-contract')){a.current.fields=null;a.current.templateContract=e.target.value;a.current.templateMonth=nextMonth(e.target.value);a.draw();return true}if(e.target.hasAttribute('data-template-month')){if(e.target.value){a.current.fields=null;a.current.templateMonth=e.target.value;a.draw()}return true}return false}
  async function submit(form,data){const fromCalendar=Boolean(a.current?.fromCalendar),kind=form.dataset.form,id=form.dataset.id,v=k=>String(data.get(k)||'').trim();const fail=message=>{const el=form.querySelector('.form-error');if(el)el.textContent=message;else a.toast(message)};
    if(kind==='receive-file'){
      const file=data.get('file');if(!file?.size||file.size>15*1024*1024){a.toast('Escolha um arquivo de até 15 MB.');return true}if(!['application/pdf','image/png','image/jpeg','image/webp'].includes(file.type)){a.toast('Use PDF, JPG, PNG ou WebP.');return true}const button=form.querySelector('[type="submit"]');button.disabled=true;
      try{const hash=Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',await file.arrayBuffer())),n=>n.toString(16).padStart(2,'0')).join('');const existing=a.scope('documents').find(d=>d.hash===hash);if(existing){if(id===('profile:'+a.company))existing.profileCompany=a.company;if(id?.startsWith('asset:')&&a.scope('assets').some(x=>x.id===id.slice(6)))addReference(a.state,existing,{kind:'asset',id:id.slice(6),purpose:'documentation'});a.save();a.open('process',existing.id);a.toast('Este arquivo já está no acervo. Abrimos o registro existente.');return true}
        const docId=uid('doc'),task=id?.startsWith('task:')?a.get('tasks',id.slice(5)):null,obligation=task?.obligation||a.scope('obligations').find(o=>o.id===id)?.id;
        await a.dbFile('put',docId,file);const d={id:docId,company:a.company,name:file.name,type:'Outro',source:v('source'),date:a.NOW,status:'A revisar',local:true,mime:file.type,size:file.size,hash,obligation,profileCompany:id===('profile:'+a.company)?a.company:undefined,asset:id?.startsWith('asset:')&&a.scope('assets').some(x=>x.id===id.slice(6))?id.slice(6):task?.asset,assetPurpose:id?.startsWith('asset:')?'documentation':'support',note:v('note')};a.state.documents.push(d);if(obligation)a.get('obligations',obligation).docs.push(docId);if(task)task.doc=docId;const p=plan(d);p.method=v('format')==='scan'||file.type.startsWith('image/')?'ocr':'direct';p.note=v('note');p.format=v('format');a.state.tasks.push({id:uid('t'),company:a.company,title:'Conferir '+file.name,due:a.NOW,owner:'Você',kind:'Documento',doc:docId,obligation,done:false});a.save();a.open('process',docId);a.render();a.toast('Original preservado neste navegador. Escolha como tratá-lo.');
      }catch{a.toast('Não foi possível guardar o arquivo. Verifique o armazenamento do navegador.')}finally{button.disabled=false}return true;
    }
    if(kind==='associate-file'){const d=a.get('documents',id),p=plan(d);d.type=v('type');d.contract=v('contract')||undefined;d.asset=v('asset')||undefined;p.note=v('note');p.stage='organized';const oid=v('obligation');if(oid){const o=a.scope('obligations').find(o=>o.id===oid);if(o&&!o.docs.includes(id))o.docs.push(id);d.obligation??=oid}d.status=data.get('reviewed')?'Revisado':'A revisar';a.save();a.closeAll();a.navigate('documents');a.open('document',id);a.toast('Organização salva. A situação financeira foi preservada.');return true}
    if(kind==='charge-template'){
      const c=a.scope('contracts').find(c=>c.id===v('contract'));if(!c){fail('Escolha um contrato desta empresa.');return true}const draft=contractTemplate(a.state,c.id,v('competence')),base=a.parseAmount(v('base')),fixed=a.parseAmount(v('fixed')),shared=a.parseAmount(v('sharedBase')),percent=Number(v('percent'));
      if([base,fixed,shared].some(n=>!Number.isSafeInteger(n)||n<0)||base<=0||!Number.isFinite(percent)||percent<0||percent>100){fail('Revise os valores e o percentual informado.');return true}
      if(v('due')<c.start||v('due')>c.end){fail('O vencimento está fora da vigência do contrato.');return true}
      if(a.state.obligations.some(o=>o.company===a.company&&o.contract===c.id&&o.competence===draft.competence)){fail('Já existe uma cobrança deste contrato nesta competência. Escolha outro período ou abra a obrigação existente.');return true}
      const rate=Math.round(shared*percent/100);if(rate>0&&!v('sourceDoc')){fail('Vincule o documento de origem do rateio antes de continuar.');return true}draft.items[0].amount=base;if(base!==c.base)draft.items[0].rule+=' · valor ajustado nesta cobrança';if(rate>0)draft.items.push({name:'Rateio de obrigação',amount:rate,nature:'Valor a recuperar · revisar',rule:`${money(shared)} × ${percent}% = ${money(rate)}`,doc:v('sourceDoc')});if(fixed>0)draft.items.push({name:'Encargo contratual',amount:fixed,nature:'Encargo · revisar',rule:`Valor informado nesta competência; revisar contrato ${c.number}`});draft.due=v('due');draft.account=v('account');draft.note=v('note');a.current.fields=Object.fromEntries(data.entries());a.open('charge-review');a.current.draft=draft;a.draw();return true;
    }
    if(kind==='obligation-template'){const amount=a.parseAmount(v('amount'));if(!Number.isSafeInteger(amount)||amount<=0){fail('Informe um valor positivo válido.');return true}const id=uid('o'),doc=v('doc');a.state.obligations.push({id,company:a.company,title:v('title'),party:v('party'),kind:'out',due:v('due'),competence:v('due').slice(0,7),asset:v('asset')||undefined,account:v('account'),docs:doc?[doc]:[],items:[{name:v('title'),amount,nature:v('model'),rule:'Criado a partir do modelo; classificação sujeita à revisão',doc:doc||undefined}]});if(doc){const d=a.get('documents',doc);d.obligation??=id}a.save();a.setMonth(v('due').slice(0,7));if(fromCalendar)a.selectDate(v('due'));a.closeAll();a.navigate(fromCalendar?'home':'obligations');a.open('obligation',id);a.toast('Obrigação prevista criada a partir do modelo.');return true}
    if(kind==='task-template'){const id=uid('t'),doc=v('doc'),o=v('obligation')||(doc?a.get('documents',doc)?.obligation:undefined);a.state.tasks.push({id,company:a.company,title:v('model')+(v('detail')?' · '+v('detail'):''),due:v('due'),owner:v('owner'),kind:v('model'),doc:doc||undefined,obligation:o||undefined,done:false});a.save();if(fromCalendar)a.selectDate(v('due'));a.closeAll();a.navigate(fromCalendar?'home':'tasks');a.open('task',id);a.toast('Tarefa criada com o contexto selecionado.');return true}
    return false;
  }
  return {dialog,click,change,submit,documentExtras};
}
